const char INDEX_HTML[] = R"rawliteral(
<!DOCTYPEhtml><htmllang="id"><head><metacharset="UTF-8"><metaname="viewport"content="width=device-width,initial-scale=1.0"><title>ESPFileManager</title><style>:root{--primary:#2563eb;--danger:#dc2626;--bg:#f8fafc;--card:#ffffff;}body{font-family:system-ui,sans-serif;background:var(--bg);margin:0;padding:20px;color:#1e293b;}.container{max-width:800px;margin:0auto;}.card{background:var(--card);padding:20px;border-radius:12px;box-shadow:04px6px-1pxrgb(000/0.1);}h2{margin-top:0;display:flex;justify-content:space-between;align-items:center;}/*UploadSection*/.upload-zone{border:2pxdashed#cbd5e1;padding:20px;text-align:center;border-radius:8px;margin-bottom:20px;transition:0.3s;}.upload-zone:hover{border-color:var(--primary);background:#eff6ff;}input[type="file"]{margin-bottom:10px;}/*TableStyle*/table{width:100%;border-collapse:collapse;margin-top:10px;}th,td{padding:12px;text-align:left;border-bottom:1pxsolid#e2e8f0;}th{background:#f1f5f9;font-weight:600;}.btn{padding:8px16px;border-radius:6px;border:none;cursor:pointer;font-weight:500;transition:0.2s;}.btn-upload{background:var(--primary);color:white;}.btn-delete{background:#fee2e2;color:var(--danger);font-size:0.85rem;}.btn-delete:hover{background:var(--danger);color:white;}.btn-refresh{background:#e2e8f0;color:#475569;font-size:0.9rem;}.status{margin-top:10px;padding:10px;border-radius:6px;display:none;}.loading{opacity:0.5;pointer-events:none;}</style></head><body><divclass="container"><divclass="card"><h2>📁FileManager<buttonclass="btnbtn-refresh"onclick="fetchFiles()">🔄Refresh</button></h2><divclass="upload-zone"><inputtype="file"id="fileInput"><buttonclass="btnbtn-upload"onclick="uploadFile()">UploadFile</button><divid="uploadStatus"class="status"></div></div><divid="tableContainer"><table><thead><tr><th>NamaFile</th><th>Ukuran</th><thstyle="text-align:right;">Aksi</th></tr></thead><tbodyid="fileList"></tbody></table></div></div></div><script>constfileListElement=document.getElementById('fileList');constuploadStatus=document.getElementById('uploadStatus');//1.AMBILDAFTARFILE(GET/fs/list)asyncfunctionfetchFiles(){try{constresponse=awaitfetch('/fs/list');constfiles=awaitresponse.json();//Ekspektasireturn:[{"name":"test.txt","size":123}]fileListElement.innerHTML='';files.forEach(file=>{constrow=`<tr><td>${file.name}</td><td>${formatBytes(file.size)}</td><tdstyle="text-align:right;"><buttonclass="btnbtn-delete"onclick="deleteFile('${file.name}')">Hapus</button></td></tr>`;fileListElement.innerHTML+=row;});}catch(err){console.error('Gagalmengambilfile:',err);}}//2.UPLOADFILE(POST/fs/upload)asyncfunctionuploadFile(){constfileInput=document.getElementById('fileInput');if(fileInput.files.length===0)returnalert('Pilihfiledulu!');constformData=newFormData();formData.append('data',fileInput.files[0],'/'+fileInput.files[0].name);showStatus('Sedangmengunggah...','#e0f2fe','#0369a1');try{constresponse=awaitfetch('/fs/upload',{method:'POST',body:formData});if(response.ok){showStatus('UploadBerhasil!','#dcfce7','#15803d');fileInput.value='';fetchFiles();}else{thrownewError('Uploadgagal');}}catch(err){showStatus('Gagal:'+err.message,'#fee2e2','#b91c1c');}}//3.HAPUSFILE(POST/fs/delete)asyncfunctiondeleteFile(path){if(!confirm(`Hapusfile${path}?`))return;constformData=newFormData();formData.append('path','/'+path);try{constresponse=awaitfetch('/fs/delete',{method:'POST',body:formData});if(response.ok){fetchFiles();}else{alert('Gagalmenghapusfile');}}catch(err){console.error('Error:',err);}}//Helper:FormatUkuranFilefunctionformatBytes(bytes,decimals=2){if(bytes===0)return'0Bytes';constk=1024;constdm=decimals<0?0:decimals;constsizes=['Bytes','KB','MB','GB'];consti=Math.floor(Math.log(bytes)/Math.log(k));returnparseFloat((bytes/Math.pow(k,i)).toFixed(dm))+''+sizes[i];}//Helper:TampilkanNotifikasifunctionshowStatus(msg,bg,color){uploadStatus.innerText=msg;uploadStatus.style.display='block';uploadStatus.style.backgroundColor=bg;uploadStatus.style.color=color;setTimeout(()=>{uploadStatus.style.display='none';},3000);}//Loaddatapertamakaliwindow.onload=fetchFiles;</script></body></html>
)rawliteral";
